import os, select, signal, subprocess, sys, time, tty
# Timed private-PTY feeder: SHELL runs CHILD with stdin/stdout/stderr on the raw slave of a pty this helper
# owns (child stays in this session and ignores SIGHUP). After the shell's FEED-READY marker and 5 consecutive
# sleeping samples, the helper writes TOKENS to the master (hex bytes, or sNNN to wait NNN ms while draining).
# It then waits for NREADS-1 'K' markers (one per decoded key), checks the shell is blocked in its last read,
# and closes the master so that read sees end of input. If the shell exits before that (master EOF/EIO), the
# helper drains to end of output, records read-count N and child-exited-early instead of polling; each feed
# has a 7 s bound.
CHILD = r"""
cd "$1" || exit 1
eval "$4"
printf 'FEED-READY\n'
for (( i = 0; i < $2; i++ )); do eval "$3" >> keys; printf 'K\n'; done
printf 'end\n' > done
"""
shell, where, nreads, reader, pre = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4], sys.argv[5]
tokens = sys.argv[6:]
seen, eof = b'', False
def note(s):
    print(s, flush=True)
def pump(until):
    global seen, eof
    while not eof:
        left = until - time.monotonic()
        if left <= 0:
            return
        if select.select([master], [], [], min(left, 0.005))[0]:
            try:
                data = os.read(master, 4096)
            except OSError:
                data = b''
            if data:
                seen += data
            else:
                eof = True
    time.sleep(max(0, until - time.monotonic()))
def blocked_for(samples, deadline):
    run = 0
    while run < samples and time.monotonic() < deadline:
        if child.poll() is not None:
            return False
        try:
            st = open('/proc/%d/stat' % child.pid).read().rsplit(')', 1)[1].split()[0]
        except OSError:
            return False
        run = run + 1 if st == 'S' else 0
        pump(time.monotonic() + 0.02)
    return run >= samples
master, slave = os.openpty()
tty.setraw(slave)
child = subprocess.Popen([shell, '--noprofile', '--norc', '-c', CHILD, 'tfeed', where, str(nreads), reader, pre],
                         stdin=slave, stdout=slave, stderr=slave, close_fds=True,
                         preexec_fn=lambda: signal.signal(signal.SIGHUP, signal.SIG_IGN))
os.close(slave)
deadline = time.monotonic() + 7
while b'FEED-READY' not in seen and not eof and time.monotonic() < deadline:
    pump(time.monotonic() + 0.05)
ready = b'FEED-READY' in seen and blocked_for(5, deadline)
note('ready blocked' if ready else 'not-ready')
if ready:
    for t in tokens:
        if t.startswith('s'):
            pump(time.monotonic() + int(t[1:]) / 1000)
        else:
            os.write(master, bytes.fromhex(t))
    while seen.count(b'K\n') < nreads - 1 and not eof and time.monotonic() < deadline:
        pump(time.monotonic() + 0.05)
    if seen.count(b'K\n') == nreads - 1 and blocked_for(5, deadline):
        note('all-read')
    else:
        while not eof and time.monotonic() < deadline:
            pump(time.monotonic() + 0.05)
        note('read-count %d' % seen.count(b'K\n'))
        try:
            child.wait(timeout=1)
            note('child-exited-early')
        except subprocess.TimeoutExpired:
            pass
os.close(master)
note('master-closed')
try:
    status = child.wait(timeout=3)
except subprocess.TimeoutExpired:
    child.kill(); status = child.wait(); note('killed-after-timeout')
note('child-exit %d' % status)
